import {Plus, Trash2} from 'lucide-react';
import {useState} from 'react';
import {get, useFieldArray, useFormContext} from 'react-hook-form';
import {ProductValues} from '@/lib/validation/productSchema';

const QUICK_FINISHES = ['Walnut', 'Teak Natural', 'Honey', 'Wenge Dark'];

/**
 * Variant x finish table. Variant SKUs are generated by the backend; leaving a
 * saved row out turns it off (it stays for stock and order history).
 */
const VariantEditor = ({
  disabled,
  lockSavedPrices,
}: {
  disabled?: boolean;
  /** Saved variants' prices are changed in the shop (D-13); new rows may set one */
  lockSavedPrices?: boolean;
}) => {
  const {
    control,
    register,
    getValues,
    formState: {errors},
  } = useFormContext<ProductValues>();
  const {fields, append, remove} = useFieldArray({control, name: 'variants'});
  const [quickName, setQuickName] = useState('');
  const listError = get(errors, 'variants')?.message as string | undefined;

  const addFinishes = () => {
    const variantName = quickName.trim();
    if (!variantName) return;
    QUICK_FINISHES.forEach((finish) =>
      append({
        variantName,
        finish,
        mrp: '',
        sellingPrice: '',
        wholesalePrice: '',
        isActive: true,
      }),
    );
    setQuickName('');
  };

  const cell = 'field-input px-2 py-1.5 text-body-sm';

  return (
    <div>
      <div className="overflow-x-auto">
        <table className="w-full min-w-[36rem] text-left">
          <thead>
            <tr className="text-label-caps uppercase text-outline">
              <th className="pb-2 pr-2 font-semibold">Variant *</th>
              <th className="pb-2 pr-2 font-semibold">Finish *</th>
              <th className="pb-2 pr-2 font-semibold">MRP</th>
              <th className="pb-2 pr-2 font-semibold">Price</th>
              <th className="pb-2 pr-2 font-semibold">Stock</th>
              <th className="pb-2 pr-2 font-semibold">On</th>
              <th className="pb-2" />
            </tr>
          </thead>
          <tbody>
            {fields.map((row, i) => {
              const err = (k: string) =>
                get(errors, `variants.${i}.${k}`)?.message as
                  | string
                  | undefined;
              const rowError =
                err('variantName') ??
                err('finish') ??
                err('sellingPrice') ??
                err('mrp');
              return (
                <tr key={row.id} className="align-top">
                  <td className="pb-2 pr-2">
                    <input
                      {...register(`variants.${i}.variantName`)}
                      aria-label={`Variant ${i + 1} name`}
                      aria-invalid={!!err('variantName')}
                      placeholder="3 Seater"
                      className={cell}
                    />
                  </td>
                  <td className="pb-2 pr-2">
                    <input
                      {...register(`variants.${i}.finish`)}
                      aria-label={`Variant ${i + 1} finish`}
                      aria-invalid={!!err('finish')}
                      placeholder="Walnut"
                      className={cell}
                    />
                  </td>
                  <td className="pb-2 pr-2">
                    <input
                      {...register(`variants.${i}.mrp`)}
                      disabled={
                        lockSavedPrices && !!getValues(`variants.${i}.id`)
                      }
                      inputMode="decimal"
                      aria-label={`Variant ${i + 1} MRP`}
                      aria-invalid={!!err('mrp')}
                      placeholder="Same"
                      className={cell}
                    />
                  </td>
                  <td className="pb-2 pr-2">
                    <input
                      {...register(`variants.${i}.sellingPrice`)}
                      disabled={
                        lockSavedPrices && !!getValues(`variants.${i}.id`)
                      }
                      inputMode="decimal"
                      aria-label={`Variant ${i + 1} price`}
                      aria-invalid={!!err('sellingPrice')}
                      placeholder="Same"
                      className={cell}
                    />
                  </td>
                  <td className="pb-2 pr-2 pt-2 text-body-sm text-outline">
                    {row.available ?? '–'}
                  </td>
                  <td className="pb-2 pr-2 pt-2">
                    <input
                      type="checkbox"
                      {...register(`variants.${i}.isActive`)}
                      aria-label={`Variant ${i + 1} active`}
                      className="h-4 w-4 accent-burgundy"
                    />
                  </td>
                  <td className="pb-2">
                    <button
                      type="button"
                      onClick={() => remove(i)}
                      disabled={disabled || fields.length === 1}
                      aria-label={`Remove variant ${i + 1}`}
                      className="btn-icon h-8 w-8 hover:text-error disabled:opacity-30"
                    >
                      <Trash2 size={14} />
                    </button>
                    {rowError && (
                      <p role="alert" className="field-error whitespace-nowrap">
                        {rowError}
                      </p>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {listError && (
        <p role="alert" className="field-error">
          {listError}
        </p>
      )}
      {!disabled && (
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={() =>
              append({
                variantName: '',
                finish: '',
                mrp: '',
                sellingPrice: '',
                wholesalePrice: '',
                isActive: true,
              })
            }
            className="btn-text"
          >
            <Plus size={12} /> Add variant
          </button>
          <span className="text-xs text-outline">
            or add common wood finishes for
          </span>
          <input
            value={quickName}
            onChange={(e) => setQuickName(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                addFinishes();
              }
            }}
            placeholder="e.g. 3 Seater"
            aria-label="Variant to add in common finishes"
            className="field-input w-36 px-2 py-1 text-sm"
          />
          <button type="button" onClick={addFinishes} className="btn-text">
            Add finishes
          </button>
        </div>
      )}
    </div>
  );
};

export default VariantEditor;
